        const { SAMLRequest, RelayState } = req.query;

        try {
            if (req.session) {
                req.session.destroy();
            }

            if (SAMLRequest) {
                const decoded = SAMLService.decodeSAMLRequest(SAMLRequest);

                const requestIdMatch = decoded?.match(/ID="([^"]+)"/);
                const destinationMatch = decoded?.match(/Destination="([^"]+)"/);

