const config = require('../config/config');

const User = require('../models/User');
const { validationResult } = require('express-validator');


class AuthController {
    static showRegister(req, res) {
        res.render('register', {
            title: 'User Registration',
            errors: [],
            formData: {}
        });
    }

    static async register(req, res) {
        const errors = validationResult(req);

        if (!errors.isEmpty()) {
            return res.render('register', {
                title: 'User Registration',
                errors: errors.array(),
                formData: req.body
            });
        }

        const { username, email, password, type, invitationCode, displayName, department } = req.body;

        try {
            const existingUser = await User.findByUsername(username);
            if (existingUser) {
                return res.render('register', {
                    title: 'User Registration',
                    errors: [{ msg: 'Username already exists' }],
                    formData: req.body
                });
            }

            const existingEmail = await User.findByEmail(email);
            if (existingEmail) {
                return res.render('register', {
                    title: 'User Registration',
                    errors: [{ msg: 'Email already registered' }],
                    formData: req.body
                });
            }


            if (parseInt(type) === 0) {
                if (!invitationCode || invitationCode !== config.getInviteCode()) {
                    return res.render('register', {
                        title: 'User Registration',
                        errors: [{ msg: 'Invalid invitation code' }],
                        formData: req.body
                    });
                }

            }

            req.session.userId = await User.create({
                username,
                email,
                password,
                type,
                displayName: displayName || username,
                department,
                role: 'user'
            });
            req.session.username = username;
            req.session.userType = type;
            req.session.userRole = 'user';

            res.redirect('/portal');
        } catch (error) {
            console.error('[Auth] User registration failed:', error.message);
            console.error(error);
            res.render('register', {
                title: 'User Registration',
                errors: [{ msg: 'Registration failed, please try again later' }],
                formData: req.body
            });
        }
    }

